import { between, check, exactSet, field, type CloudCheck, type CloudLesson, type CloudPlan } from "./model";

const architectureSource = { label: "AWS Well-Architected Framework", url: "https://docs.aws.amazon.com/wellarchitected/latest/framework/welcome.html" };
const kubernetesSource = { label: "Kubernetes: Deployments", url: "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/" };
const sreSource = { label: "Google SRE Workbook", url: "https://sre.google/workbook/table-of-contents/" };
const nistSource = { label: "NIST SP 800-207: Zero Trust Architecture", url: "https://csrc.nist.gov/pubs/sp/800/207/final" };
const finopsSource = { label: "FinOps Framework", url: "https://www.finops.org/framework/" };

type LessonSeed = {
  id: number; title: string; minutes: number; objective: string; story: string;
  concepts: CloudLesson["concepts"]; example: string; exampleNote: string; mistake: string; mission: string;
  starter: CloudPlan; solution: CloudPlan; help: Record<string, string>; checks: CloudCheck[];
  source: CloudLesson["source"];
};

const lesson = (seed: LessonSeed): CloudLesson => ({
  ...seed,
  fields: Object.entries(seed.solution).map(([key, value]) => field(key, Array.isArray(value) ? "strings" : typeof value as "string" | "number" | "boolean", seed.help[key] ?? "Required scenario value.")),
  observations: (plan) => seed.checks.map((item) => item.name + ": " + (item.test(plan) ? "ready" : "needs repair") + "."),
});

const ordered = (value: unknown, expected: string[]) => Array.isArray(value) && value.length === expected.length && value.every((item, index) => item === expected[index]);

